  IEnumerator MoveToward(int id,float seconds,float pixels){var until=Time.realtimeSinceStartup+seconds;while(Active()&&Time.realtimeSinceStartup<until){var enemy=EnemyById(id,false);if(!enemy.HasValue)yield break;var dx=enemy.Value.ScreenPosition.x-probe.PlayerScreenPosition.x;if(Mathf.Abs(dx)<=pixels)yield break;yield return input.Frame(dx>0?Key.D:Key.A);}}
