  bool CleanMenu(){probe=FindProbe();return probe!=null&&probe.CurrentScreen==NoirScreen.Menu&&probe.CurrentRoomIndex==-1&&probe.RoomCount==5&&probe.Bonds==3&&probe.MaximumBonds==3&&probe.DashCharges==probe.MaximumDashCharges&&probe.DefeatedEnemyCount==0&&probe.SoftRespawnCount==0&&probe.GlobalRespawnCount==0&&probe.LastRespawnKind==NoirRespawnKind.None;}
  IEnumerator WaitClean(float seconds){var until=Time.realtimeSinceStartup+seconds;while(Time.realtimeSinceStartup<until){probe=FindProbe();if(CleanMenu())yield break;yield return null;}probe=FindProbe();}
